-- Generated from user-supplied Ultra Moon dimensions + pokeplatinum English Dex text.
-- Source dimensions are decimeters; stored heightM is meters (not decimeters).
return {
  [1]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=15.2,weightKg=6.9,text="For some time after its birth, it grows by gaining nourishment from the seed on its back."},
  [2]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=28.7,weightKg=13.0,text="When the bud on its back starts swelling, a sweet aroma wafts to indicate the flower’s coming bloom."},
  [3]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=220.5,weightKg=100.0,text="After a rainy day, the flower on its back smells stronger. The scent attracts other Pokémon."},
  [4]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=18.7,weightKg=8.5,text="The fire on the tip of its tail is a measure of its life. If healthy, its tail burns intensely."},
  [5]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=41.9,weightKg=19.0,text="In the rocky mountains where CHARMELEON live, their fiery tails shine at night like stars."},
  [6]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=199.5,weightKg=90.5,text="It is said that CHARIZARD’s fire burns hotter if it has experienced harsh battles."},
  [7]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=19.8,weightKg=9.0,text="It shelters itself in its shell, then strikes back with spouts of water at every opportunity."},
  [8]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=49.6,weightKg=22.5,text="It is said to live 10,000 years. Its furry tail is popular as a symbol of longevity."},
  [9]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=188.5,weightKg=85.5,text="The jets of water it spouts from the rocket cannons on its shell can punch through thick steel."},
  [10]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=6.4,weightKg=2.9,text="It releases a stench from its red antenna to repel enemies. It grows by molting repeatedly."},
  [11]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=21.8,weightKg=9.9,text="A steel-hard shell protects its tender body. It quietly endures hardships while awaiting evolution."},
  [12]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=70.5,weightKg=32.0,text="It loves the honey of flowers and can locate flower patches that have even tiny amounts of pollen."},
  [13]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=7.1,weightKg=3.2,text="It eats its weight in leaves every day. It fends off attackers with the needle on its head."},
  [14]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=22.0,weightKg=10.0,text="While awaiting evolution, it hides from predators under leaves and in nooks of branches."},
  [15]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=65.0,weightKg=29.5,text="Its best attack involves flying around at high speed, striking with poison needles, then flying off."},
  [16]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=4.0,weightKg=1.8,text="It is docile and prefers to avoid conflict. If disturbed, however, it can ferociously strike back."},
  [17]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=66.1,weightKg=30.0,text="It flies over its wide territory in search of prey, downing it with its highly developed claws."},
  [18]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=87.1,weightKg=39.5,text="By flapping its wings with all its might, PIDGEOT can make a gust of wind capable of bending tall trees."},
  [19]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=7.7,weightKg=3.5,text="Cautious in the extreme, its hardy vitality lets it live in any kind of environment."},
  [20]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=40.8,weightKg=18.5,text="It whittles its constantly growing fangs by gnawing on hard things. It can chew apart cinder walls."},
  [21]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=4.4,weightKg=2.0,text="It flaps its small wings busily to fly. Using its beak, it searches in grass for prey."},
  [22]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=83.8,weightKg=38.0,text="It has the stamina to fly all day on its broad wings. It fights by using its sharp beak."},
  [23]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=15.2,weightKg=6.9,text="It sneaks through grass without making a sound and strikes unsuspecting prey from behind."},
  [24]={kind="POKEMON",heightFt=11,heightIn=6,heightM=3.5,weight=143.3,weightKg=65.0,text="The pattern on its belly is for intimidation. It constricts foes while they are frozen in fear."},
  [25]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=13.2,weightKg=6.0,text="It lives in forests with others. It stores electricity in the pouches on its cheeks."},
  [26]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=66.1,weightKg=30.0,text="It turns aggressive if it has too much electricity in its body. It discharges power through its tail."},
  [27]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=26.5,weightKg=12.0,text="To protect itself from attackers, it curls up into a ball. It lives in arid regions with minimal rainfall."},
  [28]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=65.0,weightKg=29.5,text="It curls up, then rolls into foes with its back. Its sharp spines inflict severe damage."},
  [29]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=15.4,weightKg=7.0,text="While it does not prefer to fight, even one drop of the poison it secretes from barbs can be fatal."},
  [30]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=44.1,weightKg=20.0,text="When it senses danger, it raises all the barbs on its body. These barbs grow slower than NIDORINO’s."},
  [31]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=132.3,weightKg=60.0,text="Its entire body is armored with hard scales. It will protect the young in its burrow with its life."},
  [32]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=19.8,weightKg=9.0,text="It scans its surroundings by raising its ears out of the grass. Its toxic horn is for protection."},
  [33]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=43.0,weightKg=19.5,text="It has a violent disposition and stabs foes with its horn, which oozes poison upon impact."},
  [34]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=136.7,weightKg=62.0,text="One swing of its mighty tail can snap a telephone pole as if it were a matchstick."},
  [35]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=16.5,weightKg=7.5,text="Thought to live with others on quiet mountains, it is popular for its adorable nature."},
  [36]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=88.2,weightKg=40.0,text="Rarely seen by people, it is said to be drawn by the full moon to play at deserted lakes."},
  [37]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=21.8,weightKg=9.9,text="It controls balls of fire. As it grows, its six tails split from their tips to make more tails."},
  [38]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=43.9,weightKg=19.9,text="Its nine tails are said to be imbued with a mystic power. It can live for a thousand years."},
  [39]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=12.1,weightKg=5.5,text="When it wavers its big, round eyes, it begins singing a lullaby that makes everyone drowsy."},
  [40]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=26.5,weightKg=12.0,text="Its fine fur feels sublime to the touch. It can expand its body by inhaling air."},
  [41]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=16.5,weightKg=7.5,text="Even though it has no eyes, it can sense obstacles using ultrasonic waves it emits from its mouth."},
  [42]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=121.3,weightKg=55.0,text="It loves the blood of humans and Pokémon. It flies around at night in search of neck veins."},
  [43]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=11.9,weightKg=5.4,text="It often plants its root feet in the ground during the day and sows seeds as it walks about at night."},
  [44]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=19.0,weightKg=8.6,text="The honey it drools from its mouth smells so atrocious, it can curl noses more than a mile away."},
  [45]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=41.0,weightKg=18.6,text="Its petals are the largest in the world. As it walks, it scatters extremely allergenic pollen."},
  [46]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=11.9,weightKg=5.4,text="Mushrooms named tochukaso grow on its back. They grow along with the host PARAS."},
  [47]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=65.0,weightKg=29.5,text="A mushroom grown larger than the host’s body controls PARASECT. It scatters poisonous spores."},
  [48]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=66.1,weightKg=30.0,text="Its big eyes are actually clusters of tiny eyes. At night, its kind is drawn by light."},
  [49]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=27.6,weightKg=12.5,text="It flutters its wings to scatter dustlike scales. The scales leach toxins if they contact skin."},
  [50]={kind="POKEMON",heightFt=0,heightIn=8,heightM=0.2,weight=1.8,weightKg=0.8,text="A Pokémon that lives underground. Because of its dark habitat, it is repelled by bright sunlight."},
  [51]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=73.4,weightKg=33.3,text="Its three heads move alternately, driving it through tough soil to depths of over 60 miles."},
  [52]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=9.3,weightKg=4.2,text="It is nocturnal in nature. If it spots something shiny, its eyes glitter brightly."},
  [53]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=70.5,weightKg=32.0,text="A very haughty Pokémon. Among fans, the size of the jewel in its forehead is a topic of much talk."},
  [54]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=43.2,weightKg=19.6,text="If its usual headache worsens, it starts exhibiting odd powers. It can’t remember doing so, however."},
  [55]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=168.9,weightKg=76.6,text="A Pokémon that lives in lakes. It swims faster than any human swimming champion."},
  [56]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=61.7,weightKg=28.0,text="It lives in treetop colonies. If one becomes enraged, the whole colony rampages for no reason."},
  [57]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=70.5,weightKg=32.0,text="It grows angry if you see its eyes and gets angrier if you run. If you beat it, it gets even madder."},
  [58]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=41.9,weightKg=19.0,text="A Pokémon with a loyal nature. It will remain motionless until it is given an order by its Trainer."},
  [59]={kind="POKEMON",heightFt=6,heightIn=3,heightM=1.9,weight=341.7,weightKg=155.0,text="Its proud and regal appearance has captured the hearts of people since long ago."},
  [60]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=27.3,weightKg=12.4,text="Its skin is so thin, its internal organs are visible. It has trouble walking on its newly grown feet."},
  [61]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=44.1,weightKg=20.0,text="The spiral pattern on its belly subtly undulates. Staring at it gradually causes drowsiness."},
  [62]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=119.0,weightKg=54.0,text="With its extremely tough muscles, it can keep swimming in the Pacific Ocean without resting."},
  [63]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=43.0,weightKg=19.5,text="It sleeps for 18 hours a day. Even when awake, it teleports itself while remaining seated."},
  [64]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=124.6,weightKg=56.5,text="If one is nearby, an eerie shadow appears on TV screens. Seeing the shadow is said to bring bad luck."},
  [65]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=105.8,weightKg=48.0,text="Its superb memory lets it recall everything it has experienced from birth. Its IQ exceeds 5,000."},
  [66]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=43.0,weightKg=19.5,text="It hefts a GRAVELER repeatedly to strengthen its entire body. It uses every type of martial arts."},
  [67]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=155.4,weightKg=70.5,text="MACHOKE’s boundless power is very dangerous, so it wears a belt that suppresses its energy."},
  [68]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=286.6,weightKg=130.0,text="It punches with its four arms at blinding speed. It can launch 1,000 punches in two seconds."},
  [69]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=8.8,weightKg=4.0,text="It prefers hot and humid environments. It is quick at capturing prey with its vines."},
  [70]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=14.1,weightKg=6.4,text="A Pokémon that appears to be a plant. It captures unwary prey by dousing them with a toxic powder."},
  [71]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=34.2,weightKg=15.5,text="It pools in its mouth a fluid with a honeylike scent, which is really an acid that dissolves anything."},
  [72]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=100.3,weightKg=45.5,text="Its body is virtually composed of water. It shoots strange beams from its crystal-like eyes."},
  [73]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=121.3,weightKg=55.0,text="With 80 tentacles for ensnaring victims, it prevents escape until the prey is weakened by poison."},
  [74]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=44.1,weightKg=20.0,text="Many live on mountain trails and remain half buried while keeping an eye on climbers."},
  [75]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=231.5,weightKg=105.0,text="GRAVELER make their homes on sheer cliff faces by gouging out numerous horizontal holes."},
  [76]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=661.4,weightKg=300.0,text="It sheds its hide once a year. Its boulderlike body is so tough, even dynamite can’t harm it."},
  [77]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=66.1,weightKg=30.0,text="About an hour after birth, its fiery mane and tail grow out, giving it an impressive appearance."},
  [78]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=209.4,weightKg=95.0,text="It gallops at nearly 150 mph. With its mane blazing ferociously, it races as if it were an arrow."},
  [79]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=79.4,weightKg=36.0,text="Although slow, it is skilled at fishing with its tail. It does not feel pain if its tail is bitten."},
  [80]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=173.1,weightKg=78.5,text="Though usually dim witted, it seems to become inspired if the SHELLDER on its tail bites down."},
  [81]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=13.2,weightKg=6.0,text="The units at its sides generate electromagnetic waves that keep it airborne. It feeds on electricity."},
  [82]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=132.3,weightKg=60.0,text="It is actually three MAGNEMITE linked by magnetism. A group can set off a magnetic storm."},
  [83]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=33.1,weightKg=15.0,text="It can’t live without the stalk it holds. That’s why it defends the stalk from attackers with its life."},
  [84]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=86.4,weightKg=39.2,text="The brains in its two heads appear to communicate emotions to each other with a telepathic power."},
  [85]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=187.8,weightKg=85.2,text="When DODUO evolves into this odd breed, one of its heads splits into two. It runs at nearly 40 mph."},
  [86]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=198.4,weightKg=90.0,text="A Pokémon that lives on icebergs. It swims in the sea using the point on its head to break up ice."},
  [87]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=264.6,weightKg=120.0,text="In snow, the pure white coat covering its body obscures it from predators."},
  [88]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=66.1,weightKg=30.0,text="It was born when sludge in a dirty stream was exposed to the moon’s X-rays. It appears among filth."},
  [89]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=66.1,weightKg=30.0,text="A toxic fluid seeps from its body. The fluid instantly kills plants and trees on contact."},
  [90]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=8.8,weightKg=4.0,text="It swims backward by opening and closing its two shells. Its large tongue is always kept hanging out."},
  [91]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=292.1,weightKg=132.5,text="It fights by keeping its shell tightly shut for protection and by shooting spikes to repel foes."},
  [92]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=0.2,weightKg=0.1,text="This Pokémon’s body is 95% made up of gases, which are blown away by strong gusts of wind."},
  [93]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=0.2,weightKg=0.1,text="It can slip through any obstacle. It lurks inside walls to keep an eye on its foes."},
  [94]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=89.3,weightKg=40.5,text="It hides in shadows. It is said that if GENGAR is hiding, it cools the area by nearly 10 degrees F."},
  [95]={kind="POKEMON",heightFt=28,heightIn=10,heightM=8.8,weight=463.0,weightKg=210.0,text="When it travels underground, it causes rumbling and tremors. It can move at 50 mph."},
  [96]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=71.4,weightKg=32.4,text="It can tell what people are dreaming by sniffing with its big nose. It loves fun dreams."},
  [97]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=166.7,weightKg=75.6,text="Seeing its swinging pendulum can induce sleep in three seconds, even in someone who just woke up."},
  [98]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=14.3,weightKg=6.5,text="It lives in burrows dug on sandy beaches. Its pincers fully grow back if they are broken in battle."},
  [99]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=132.3,weightKg=60.0,text="The larger pincer has 10,000- horsepower strength. However, it is so heavy, it is difficult to aim."},
  [100]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=22.9,weightKg=10.4,text="It looks just like a Poké Ball. It is dangerous because it may electrocute or explode on touch."},
  [101]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=146.8,weightKg=66.6,text="It is known to drift on winds if it is bloated to bursting with stored electricity."},
  [102]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=5.5,weightKg=2.5,text="Its six eggs converse using telepathy. They can quickly gather if they become separated."},
  [103]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=264.6,weightKg=120.0,text="It is called “The Walking Jungle.” If a head grows too big, it falls off and becomes an EXEGGCUTE."},
  [104]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=14.3,weightKg=6.5,text="When it thinks of its dead mother, it cries. Its crying makes the skull it wears rattle hollowly."},
  [105]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=99.2,weightKg=45.0,text="From its birth, this savage Pokémon constantly holds bones. It is skilled in using them as weapons."},
  [106]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=109.8,weightKg=49.8,text="Its legs can stretch double. First-time foes are startled by its extensible reach."},
  [107]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=110.7,weightKg=50.2,text="The arm-twisting punches it throws pulverize even concrete. It rests after three minutes of fighting."},
  [108]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=144.4,weightKg=65.5,text="Instead of hands, it uses its tongue, which is twice its height. Its sticky saliva grips anything."},
  [109]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=2.2,weightKg=1.0,text="Lighter-than-air gases in its body keep it aloft. The gases not only smell, they are also explosive."},
  [110]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=20.9,weightKg=9.5,text="It grows by feeding on gases released by garbage. Though very rare, triplets have been found."},
  [111]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=253.5,weightKg=115.0,text="Its body is clad in a thick hide, and its tackles topple buildings. Unfortunately, it is not smart."},
  [112]={kind="POKEMON",heightFt=6,heightIn=3,heightM=1.9,weight=264.6,weightKg=120.0,text="Its brain developed after it stood up on its hind legs. Its drill horn bores tunnels through solid rock."},
  [113]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=76.3,weightKg=34.6,text="It is said to deliver happiness. Being compassionate, it shares its eggs with injured people."},
  [114]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=77.2,weightKg=35.0,text="It is shrouded by blue vines. No one has seen the face hidden behind this growth of vines."},
  [115]={kind="POKEMON",heightFt=7,heightIn=3,heightM=2.2,weight=176.4,weightKg=80.0,text="It raises its offspring in its belly pouch. It lets the baby out to play only when it feels safe."},
  [116]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=17.6,weightKg=8.0,text="It makes its nest in the shade of corals. If it senses danger, it spits murky ink and flees."},
  [117]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=55.1,weightKg=25.0,text="Its spines provide protection. Its fins and bones are prized as traditional medicine ingredients."},
  [118]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=33.1,weightKg=15.0,text="It swims elegantly by flittering its tail fin as if it were a dress. It has the look of a queen."},
  [119]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=86.0,weightKg=39.0,text="It makes its nest by hollowing out boulders in streams with its horn. It defends its eggs with its life."},
  [120]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=76.1,weightKg=34.5,text="If its body is torn, it can grow back if the red core remains. The core flashes at midnight."},
  [121]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=176.4,weightKg=80.0,text="At the center of its body is a red core, which sends mysterious radio signals into the night sky."},
  [122]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=120.2,weightKg=54.5,text="It is a pantomime expert that can create invisible but solid walls using miming gestures."},
  [123]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=123.5,weightKg=56.0,text="It is nearly impossible to parry its attacking scythes. Its movements are like a ninja’s."},
  [124]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=89.5,weightKg=40.6,text="Its cries sound like human speech. However, it is impossible to tell what it is trying to say."},
  [125]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=66.1,weightKg=30.0,text="Half of all blackouts occur when this Pokémon appears at power plants and eats electricity."},
  [126]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=98.1,weightKg=44.5,text="Born in the spout of a volcano, its body is covered by flames that shimmer like the sun."},
  [127]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=121.3,weightKg=55.0,text="It grips prey with its pincers until the prey is torn in half. What it can’t tear, it tosses far."},
  [128]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=194.9,weightKg=88.4,text="Once it takes aim at its foe, it makes a headlong charge. It is famous for its violent nature."},
  [129]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=22.0,weightKg=10.0,text="It is said to be the world’s weakest Pokémon. No one knows why it has managed to survive."},
  [130]={kind="POKEMON",heightFt=21,heightIn=4,heightM=6.5,weight=518.1,weightKg=235.0,text="Once it appears, its rage never settles until it has razed the fields and mountains around it."},
  [131]={kind="POKEMON",heightFt=8,heightIn=2,heightM=2.5,weight=485.0,weightKg=220.0,text="It loves crossing the sea with people and Pokémon on its back. It understands human speech."},
  [132]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=8.8,weightKg=4.0,text="It has the ability to reconstitute its entire cellular structure to transform into whatever it sees."},
  [133]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=14.3,weightKg=6.5,text="A rare Pokémon that adapts to harsh environments by taking on different evolutionary forms."},
  [134]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=63.9,weightKg=29.0,text="It has evolved to be suitable for an aquatic life. It can invisibly melt away into water."},
  [135]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=54.0,weightKg=24.5,text="It controls 10,000-volt power and can raise all the fur on its body as if it were sharp needles."},
  [136]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=55.1,weightKg=25.0,text="It has a flame sac in its body. Its body temperature tops 1,650 degrees Fahrenheit before battle."},
  [137]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=80.5,weightKg=36.5,text="The world’s first artificially created Pokémon. It can travel through electronic space."},
  [138]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=16.5,weightKg=7.5,text="A Pokémon that was resurrected from a fossil using modern science. It swam in ancient seas."},
  [139]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=77.2,weightKg=35.0,text="It is thought that this Pokémon became extinct because its spiral shell grew too large."},
  [140]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=25.4,weightKg=11.5,text="It is thought to have inhabited beaches 300 million years ago. It is protected by a stiff shell."},
  [141]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=89.3,weightKg=40.5,text="It is thought that this Pokémon came onto land because its prey adapted to life on land."},
  [142]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=130.1,weightKg=59.0,text="A Pokémon that roamed the skies in the dinosaur era. Its teeth are like saw blades."},
  [143]={kind="POKEMON",heightFt=6,heightIn=11,heightM=2.1,weight=1014.1,weightKg=460.0,text="Its stomach can digest any kind of food, even if it happens to be moldy or rotten."},
  [144]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=122.1,weightKg=55.4,text="A legendary bird Pokémon. It can create blizzards by freezing moisture in the air."},
  [145]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=116.0,weightKg=52.6,text="A legendary Pokémon that is said to live in thunderclouds. It freely controls lightning bolts."},
  [146]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=132.3,weightKg=60.0,text="One of the legendary bird Pokémon. It is said that its appearance indicates the coming of spring."},
  [147]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=7.3,weightKg=3.3,text="It is called the “Mirage Pokémon” because so few have seen it. Its shed skin has been found."},
  [148]={kind="POKEMON",heightFt=13,heightIn=1,heightM=4.0,weight=36.4,weightKg=16.5,text="If its body takes on an aura, the weather changes instantly. It is said to live in seas and lakes."},
  [149]={kind="POKEMON",heightFt=7,heightIn=3,heightM=2.2,weight=463.0,weightKg=210.0,text="It is said to make its home somewhere in the sea. It guides crews of shipwrecks to shore."},
  [150]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=269.0,weightKg=122.0,text="A Pokémon created by recombining MEW’s genes. It’s said to have the most savage heart among Pokémon."},
  [151]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=8.8,weightKg=4.0,text="Because it can use all kinds of moves, many scientists believe MEW to be the ancestor of Pokémon."},
  [152]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=14.1,weightKg=6.4,text="It uses the leaf on its head to determine the temperature and humidity. It loves to sunbathe."},
  [153]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=34.8,weightKg=15.8,text="The buds that ring its neck give off a spicy aroma that perks people up."},
  [154]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=221.6,weightKg=100.5,text="Its breath has the fantastic ability to revive dead plants and flowers."},
  [155]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=17.4,weightKg=7.9,text="It has a timid nature. If it is startled, the flames on its back burn more vigorously."},
  [156]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=41.9,weightKg=19.0,text="It intimidates foes with the heat of its flames. The fire burns more strongly when it readies to fight."},
  [157]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=175.3,weightKg=79.5,text="It attacks using blasts of fire. It creates heat shimmers with intense fire to hide itself."},
  [158]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=20.9,weightKg=9.5,text="It has the habit of biting anything with its developed jaws. Even its Trainer needs to be careful."},
  [159]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=55.1,weightKg=25.0,text="Once it bites down, it won’t let go until it loses its fangs. New fangs quickly grow into place."},
  [160]={kind="POKEMON",heightFt=7,heightIn=7,heightM=2.3,weight=195.8,weightKg=88.8,text="It usually moves slowly, but it goes at blinding speed when it attacks and bites prey."},
  [161]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=13.2,weightKg=6.0,text="It has a very nervous nature. It stands up high on its tail so it can scan wide areas."},
  [162]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=71.7,weightKg=32.5,text="The mother puts its offspring to sleep by curling up around them. It corners foes with speed."},
  [163]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=46.7,weightKg=21.2,text="It always stands on one foot. Even when attacked, it does not brace itself using both feet."},
  [164]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=89.9,weightKg=40.8,text="Its eyes are special. They can pick out objects as long as there is the tiniest amount of light."},
  [165]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=23.8,weightKg=10.8,text="It is so timid, it can’t move if it isn’t with a swarm of others. It conveys its feelings with scent."},
  [166]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=78.5,weightKg=35.6,text="It uses starlight as energy. When more stars appear at night, the patterns on its back grow larger."},
  [167]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=18.7,weightKg=8.5,text="It sets a trap by spinning a web with thin but strong silk. It waits motionlessly for prey to arrive."},
  [168]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=73.9,weightKg=33.5,text="It attaches silk to its prey and sets it free. Later, it tracks the silk to the prey and its friends."},
  [169]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=165.3,weightKg=75.0,text="Having four wings enables it to fly faster and more quietly. It turns active when the night comes."},
  [170]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=26.5,weightKg=12.0,text="It discharges positive and negative electricity from its antenna tips to shock its foes."},
  [171]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=49.6,weightKg=22.5,text="LANTURN’s light can shine up from great depths. It is nicknamed “The Deep-Sea Star.”"},
  [172]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=4.4,weightKg=2.0,text="The electric pouches on its cheeks are still small. They cannot store much electricity yet."},
  [173]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=6.6,weightKg=3.0,text="Its silhouette is like a star. It is believed to arrive riding on shooting stars."},
  [174]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=2.2,weightKg=1.0,text="It has a soft and bouncy body. Once it starts bouncing, it becomes impossible to stop."},
  [175]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=3.3,weightKg=1.5,text="Its shell is said to be stuffed with happiness that it shares with kindhearted people."},
  [176]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=7.1,weightKg=3.2,text="It is said to appear in front of kindly people to scatter a glowing down called “joy dust.”"},
  [177]={kind="POKEMON",heightFt=0,heightIn=8,heightM=0.2,weight=4.4,weightKg=2.0,text="It picks food from cactus plants, deftly avoiding buds and spines. It seems to skip about to move."},
  [178]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=33.1,weightKg=15.0,text="This odd Pokémon can see both the past and the future. It eyes the sun’s movement all day."},
  [179]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=17.2,weightKg=7.8,text="Its fluffy coat swells to double when static electricity builds up. Touching it can be shocking."},
  [180]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=29.3,weightKg=13.3,text="If its coat becomes fully charged with electricity, its tail lights up. It fires hair that zaps on impact."},
  [181]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=135.6,weightKg=61.5,text="The tip of its tail shines brightly. In the olden days, people sent signals using the tail’s light."},
  [182]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=12.8,weightKg=5.8,text="When the heavy rainfall season ends, it is drawn out by warm sunlight to dance in the open."},
  [183]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=18.7,weightKg=8.5,text="Using its tail as a float, it dives underwater. It likes eating plants that grow on river bottoms."},
  [184]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=62.8,weightKg=28.5,text="It lives in rivers and lakes. In water, its coloring and patterns trick the vision of foes."},
  [185]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=83.8,weightKg=38.0,text="Despite appearing to be a tree, its body is closer to rocks and stones. It is very weak to water."},
  [186]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=74.7,weightKg=33.9,text="It gathers groups of others as their leader. Its cries make POLIWAG obey."},
  [187]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=1.1,weightKg=0.5,text="It drifts on winds. It is said that when HOPPIP gather in fields and mountains, spring is on the way."},
  [188]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=2.2,weightKg=1.0,text="It blooms when the weather warms. It floats in the sky to soak up as much sunlight as possible."},
  [189]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=6.6,weightKg=3.0,text="Blown by seasonal winds, it circles the globe, scattering cotton spores as it goes."},
  [190]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=25.4,weightKg=11.5,text="It uses its tail to pluck fruits that are out of reach. Its tail is more adept than its real hands."},
  [191]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=4.0,weightKg=1.8,text="It suddenly falls out of the sky in the morning. A year after a cold summer, their population explodes."},
  [192]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=18.7,weightKg=8.5,text="It gets energy from warm sunlight and is known for its habit of moving in pursuit of it."},
  [193]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=83.8,weightKg=38.0,text="Its eyes can see 360 degrees without moving its head. It won’t miss prey--even those behind it."},
  [194]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=18.7,weightKg=8.5,text="It lives in cold water, half burying itself in mud at the bottom to sleep."},
  [195]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=165.3,weightKg=75.0,text="It has a sluggish nature. It lies at the river’s bottom, waiting for prey to stray into its mouth."},
  [196]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=58.4,weightKg=26.5,text="Its fur has the look and feel of velvet. The orb on its forehead glows when it uses psycho-power."},
  [197]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=59.5,weightKg=27.0,text="The light of the moon changed EEVEE’s genetic structure. It lurks in darkness for prey."},
  [198]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=4.6,weightKg=2.1,text="It is believed that seeing this Pokémon at night will bring about ominous occurrences."},
  [199]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=175.3,weightKg=79.5,text="Being bitten by SHELLDER gave it intelligence comparable to that of award-winning scientists."},
  [200]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=2.2,weightKg=1.0,text="It loves to sneak up on people late at night, then startle them with its shrieklike cry."},
  [201]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=11.0,weightKg=5.0,text="Shaped like ancient writing, it is a huge mystery whether language or UNOWN came first."},
  [202]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=62.8,weightKg=28.5,text="It desperately tries to keep its black tail hidden. It is said to be proof the tail hides a secret."},
  [203]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=91.5,weightKg=41.5,text="Its tail also has a small brain. It bites to repel any foe trying to sneak up on it from behind."},
  [204]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=15.9,weightKg=7.2,text="It looks just like a pinecone. Its shell protects it from bird Pokémon that peck it by mistake."},
  [205]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=277.3,weightKg=125.8,text="It is encased in a steel shell. Its peering eyes are all that can be seen of its mysterious innards."},
  [206]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=30.9,weightKg=14.0,text="It digs into the ground with its tail and makes a mazelike nest. It can fly just a little."},
  [207]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=142.9,weightKg=64.8,text="It sails on the winds with its limbs extended to strike from the sky. It aims for the prey’s face."},
  [208]={kind="POKEMON",heightFt=30,heightIn=2,heightM=9.2,weight=881.8,weightKg=400.0,text="Tempered underground under high pressure and heat, its body is harder than any metal."},
  [209]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=17.2,weightKg=7.8,text="Small Pokémon flee from its scary face. It is, however, considered by women to be cute."},
  [210]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=107.4,weightKg=48.7,text="It is timid in spite of its looks. If it becomes enraged, however, it will strike with its huge fangs."},
  [211]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=8.6,weightKg=3.9,text="It shoots the poison spines on its body in all directions. Its round form makes it a poor swimmer."},
  [212]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=260.1,weightKg=118.0,text="It has a steel-hard body. It intimidates foes by upraising its eye-patterned pincers."},
  [213]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=45.2,weightKg=20.5,text="It stores berries in its shell. The berries eventually ferment to become delicious juices."},
  [214]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=119.0,weightKg=54.0,text="It gathers in forests to search for tree sap, its favorite food. It’s strong enough to hurl foes."},
  [215]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=61.7,weightKg=28.0,text="It feeds on eggs stolen from nests. Its sharply hooked claws rip vulnerable spots on prey."},
  [216]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=19.4,weightKg=8.8,text="It lets honey soak into its paws so it can lick them all the time. Every set of paws tastes unique."},
  [217]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=277.3,weightKg=125.8,text="In its territory, it leaves scratches on trees that bear delicious berries or fruits."},
  [218]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=77.2,weightKg=35.0,text="Its body is made of magma. If it doesn’t keep moving, its body will cool and harden."},
  [219]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=121.3,weightKg=55.0,text="Its body temperature is roughly 18,000 degrees F. Flames spout from gaps in its hardened shell."},
  [220]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=14.3,weightKg=6.5,text="It loves eating mushrooms that grow under dead grass. It also finds hot springs while foraging."},
  [221]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=123.0,weightKg=55.8,text="Its shaggy coat makes it unable to see. It checks surroundings with its sensitive nose instead."},
  [222]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=11.0,weightKg=5.0,text="Many live in the clean seas of the south. They apparently can’t live in polluted waters."},
  [223]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=26.5,weightKg=12.0,text="It squirts water forcefully from its mouth to shoot down flying prey."},
  [224]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=62.8,weightKg=28.5,text="It lives in the gaps of boulders and in holes on the seafloor. Its suction cups grip prey tightly."},
  [225]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=35.3,weightKg=16.0,text="It carries food rolled up in its tail. It has the habit of sharing food with people lost in mountains."},
  [226]={kind="POKEMON",heightFt=6,heightIn=11,heightM=2.1,weight=485.0,weightKg=220.0,text="When the waves are calm, one may encounter a swarm of MANTINE swimming as if they are in flight."},
  [227]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=111.3,weightKg=50.5,text="Despite being clad entirely in iron-hard armor, it flies at speeds over 180 mph."},
  [228]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=23.8,weightKg=10.8,text="It conveys its feelings using different cries. It works in a pack to cleverly take down prey."},
  [229]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=77.2,weightKg=35.0,text="Long ago, people imagined its eerie howls to be the call of the grim reaper."},
  [230]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=335.1,weightKg=152.0,text="It lives in caves on the seafloor and creates giant whirlpools every time it moves."},
  [231]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=73.9,weightKg=33.5,text="It is strong despite its compact size. It can easily pick up and carry an adult human on its back."},
  [232]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=264.6,weightKg=120.0,text="It attacks by curling up, then rolling into its foe. It can blow apart a house in one hit."},
  [233]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=71.7,weightKg=32.5,text="With planetary development software installed, it became capable of working in space."},
  [234]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=157.0,weightKg=71.2,text="Staring at its antlers creates an odd sensation as if one were being drawn into their centers."},
  [235]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=127.9,weightKg=58.0,text="It marks its territory by using its tail like a paintbrush. There are more than 5,000 different marks."},
  [236]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=46.3,weightKg=21.0,text="It is famous for its eagerness to fight and always nurses injuries from challenging larger foes."},
  [237]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=105.8,weightKg=48.0,text="It fights while spinning like a top. The centrifugal force boosts its destructive power by ten."},
  [238]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=13.2,weightKg=6.0,text="It tests everything by touching with its lips, which remember what it likes and dislikes."},
  [239]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=51.8,weightKg=23.5,text="It generates electricity by whirling its arms. However, it can’t store the energy it makes."},
  [240]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=47.2,weightKg=21.4,text="Its body temperature is around 1,100 degrees F. It is healthy if it is breathing yellow flames."},
  [241]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=166.4,weightKg=75.5,text="It is said that kids who drink MILTANK’s milk grow up to become hearty, healthy adults."},
  [242]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=103.2,weightKg=46.8,text="This kindhearted Pokémon nurses sick Pokémon to health. It senses feelings of sadness."},
  [243]={kind="POKEMON",heightFt=6,heightIn=3,heightM=1.9,weight=392.4,weightKg=178.0,text="It is said to have fallen with lightning. It can fire thunderbolts from the rain clouds on its back."},
  [244]={kind="POKEMON",heightFt=6,heightIn=11,heightM=2.1,weight=436.5,weightKg=198.0,text="It is said that when it roars, a volcano erupts somewhere around the globe."},
  [245]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=412.3,weightKg=187.0,text="It races around the world to purify fouled water. It dashes away with the north wind."},
  [246]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=158.7,weightKg=72.0,text="A Pokémon that eats soil. Once it has eaten a large mountain, it goes to sleep so it can grow."},
  [247]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=335.1,weightKg=152.0,text="Its body is as hard as bedrock. By venting pressurized gas, it can launch itself like a rocket."},
  [248]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=445.3,weightKg=202.0,text="If it rampages, it knocks down mountains and buries rivers. Maps must be redrawn afterward."},
  [249]={kind="POKEMON",heightFt=17,heightIn=1,heightM=5.2,weight=476.2,weightKg=216.0,text="It sleeps in a deep-sea trench. If it flaps its wings, it is said to cause a 40-day storm."},
  [250]={kind="POKEMON",heightFt=12,heightIn=6,heightM=3.8,weight=438.7,weightKg=199.0,text="Its feathers are in seven colors. It is said that anyone seeing it is promised eternal happiness."},
  [251]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=11.0,weightKg=5.0,text="It has the power to travel across time, but it is said to appear only in peaceful times."},
  [252]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=11.0,weightKg=5.0,text="The soles of its feet are covered by countless tiny spikes, enabling it to walk on walls and ceilings."},
  [253]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=47.6,weightKg=21.6,text="It lives in dense jungles. While closing in on its prey, it leaps from branch to branch."},
  [254]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=115.1,weightKg=52.2,text="The leaves that grow on its arms can slice down thick trees. It is without peer in jungle combat."},
  [255]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=5.5,weightKg=2.5,text="A fire burns inside, so it feels very warm to hug. It launches fireballs of 1,800 degrees F."},
  [256]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=43.0,weightKg=19.5,text="Its kicking mastery lets it loose 10 kicks per second. It emits sharp cries to intimidate foes."},
  [257]={kind="POKEMON",heightFt=6,heightIn=3,heightM=1.9,weight=114.6,weightKg=52.0,text="Flames spout from its wrists, enveloping its knuckles. Its punches scorch its foes."},
  [258]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=16.8,weightKg=7.6,text="To alert it, the fin on its head senses the flow of water. It has the strength to heft boulders."},
  [259]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=61.7,weightKg=28.0,text="Its sturdy legs give it sure footing, even in mud. It burrows into dirt to sleep."},
  [260]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=180.6,weightKg=81.9,text="It can swim while towing a large ship. It bashes down foes with a swing of its thick arms."},
  [261]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=30.0,weightKg=13.6,text="A Pokémon with a persistent nature, it chases its chosen prey until the prey becomes exhausted."},
  [262]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=81.6,weightKg=37.0,text="It chases down prey in a pack. It will never disobey the commands of a skilled Trainer."},
  [263]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=38.6,weightKg=17.5,text="It walks in zigzag fashion. It is good at finding items in the grass and even in the ground."},
  [264]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=71.7,weightKg=32.5,text="It charges prey at speeds over 60 mph. However, because it can only run straight, it often fails."},
  [265]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=7.9,weightKg=3.6,text="It loves to eat leaves. If it is attacked by a STARLY, it will defend itself with its spiked rear."},
  [266]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=22.0,weightKg=10.0,text="It anchors itself by wrapping twigs with the silk from its body. It motionlessly awaits evolution."},
  [267]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=62.6,weightKg=28.4,text="It has an aggressive nature. It stabs prey with its long, narrow mouth to drain the prey’s fluids."},
  [268]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=25.4,weightKg=11.5,text="It is hot inside its cocoon. All the cells in its body create the energy for it to evolve."},
  [269]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=69.7,weightKg=31.6,text="A nocturnal Pokémon. Drawn by streetlights, they messily eat the leaves of trees lining boulevards."},
  [270]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=5.7,weightKg=2.6,text="It looks like an aquatic plant and serves as a ferry to Pokémon that can’t swim."},
  [271]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=71.7,weightKg=32.5,text="It has a mischievous spirit. If it spots an angler, it will tug on the fishing line to interfere."},
  [272]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=121.3,weightKg=55.0,text="If it hears festive music, all its muscles fill with energy. It can’t help breaking out into a dance."},
  [273]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=8.8,weightKg=4.0,text="When it dangles from a tree branch, it looks just like an acorn. It enjoys scaring other Pokémon."},
  [274]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=61.7,weightKg=28.0,text="The sound of its grass flute makes its listeners uneasy. It lives deep in forests."},
  [275]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=131.4,weightKg=59.6,text="By flapping its leafy fan, it can whip up gusts of 100 ft/second that can level houses."},
  [276]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=5.1,weightKg=2.3,text="It has a gutsy spirit that makes it bravely take on tough foes. It flies in search of warm climates."},
  [277]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=43.7,weightKg=19.8,text="It circles the sky in search of prey. When it spots one, it dives steeply to catch the prey."},
  [278]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=20.9,weightKg=9.5,text="It makes its nest on steep sea cliffs. Riding updrafts, it soars to great heights."},
  [279]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=61.7,weightKg=28.0,text="It dips its large bill in the sea, then scoops up numerous prey along with water."},
  [280]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=14.6,weightKg=6.6,text="It uses the horns on its head to sense human emotions. It is said to appear in front of cheerful people."},
  [281]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=44.5,weightKg=20.2,text="It is highly perceptive of its Trainer’s feelings. It dances when it is feeling happy."},
  [282]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=106.7,weightKg=48.4,text="It will try to guard its trusted Trainer with its life. It has the ability to see the future."},
  [283]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=3.7,weightKg=1.7,text="It appears as if it is skating on water. It draws prey with a sweet scent from the tip of its head."},
  [284]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=7.9,weightKg=3.6,text="Its antennae have eye patterns on them. Its four wings enable it to hover and fly in any direction."},
  [285]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=9.9,weightKg=4.5,text="It spouts poison spores from the top of its head. These spores cause pain all over if inhaled."},
  [286]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=86.4,weightKg=39.2,text="Its short arms stretch when it throws punches. Its technique is equal to that of pro boxers."},
  [287]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=52.9,weightKg=24.0,text="It spends nearly all its time in a day sprawled out. Just seeing it makes one drowsy."},
  [288]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=102.5,weightKg=46.5,text="Its heart beats at a tenfold tempo, so it cannot sit still for even a moment."},
  [289]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=287.7,weightKg=130.5,text="The world’s laziest Pokémon. When it is lounging, it is actually saving energy for striking back."},
  [290]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=12.1,weightKg=5.5,text="It grows underground, sensing its surroundings using antennae instead of its virtually blind eyes."},
  [291]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=26.5,weightKg=12.0,text="Because it moves so quickly, it sometimes becomes unseeable. It congregates around tree sap."},
  [292]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=2.6,weightKg=1.2,text="A discarded bug shell that came to life. Peering into the crack on its back is said to steal one’s spirit."},
  [293]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=35.9,weightKg=16.3,text="Usually, its cries are like quiet murmurs. If frightened, it shrieks at the same volume as a jet plane."},
  [294]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=89.3,weightKg=40.5,text="The shock waves from its cries can tip over trucks. It stamps its feet to power up."},
  [295]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=185.2,weightKg=84.0,text="Its howls can be heard over six miles away. It emits all sorts of noises from the ports on its body."},
  [296]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=190.5,weightKg=86.4,text="It toughens its body by slamming into thick trees. Many snapped trees can be found near its nest."},
  [297]={kind="POKEMON",heightFt=7,heightIn=7,heightM=2.3,weight=559.5,weightKg=253.8,text="It loves to match power with big-bodied Pokémon. It can knock a truck flying with its arm thrusts."},
  [298]={kind="POKEMON",heightFt=0,heightIn=8,heightM=0.2,weight=4.4,weightKg=2.0,text="A Pokémon that lives by water. It moves quickly on land by bouncing on its big tail."},
  [299]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=213.8,weightKg=97.0,text="Its nose is a magnet. As a result, this Pokémon always keeps its face pointing north."},
  [300]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=24.3,weightKg=11.0,text="It can’t stop itself from chasing moving things, and it runs in a circle, chasing its own tail."},
  [301]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=71.9,weightKg=32.6,text="It is highly popular among female Trainers for its sublime fur. It does not keep a nest."},
  [302]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=24.3,weightKg=11.0,text="It hides in the darkness of caves. Its diet of gems has transformed its eyes into gemstones."},
  [303]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=25.4,weightKg=11.5,text="Attached to its head is a huge set of jaws formed by horns. It can chew through iron beams."},
  [304]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=132.3,weightKg=60.0,text="It usually lives deep in mountains. However, hunger may drive it to eat railroad tracks and cars."},
  [305]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=264.6,weightKg=120.0,text="For food, it digs up iron ore. It smashes its steely body against others to fight over territory."},
  [306]={kind="POKEMON",heightFt=6,heightIn=11,heightM=2.1,weight=793.7,weightKg=360.0,text="While seeking iron for food, it digs tunnels by breaking through bedrock with its steel horns."},
  [307]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=24.7,weightKg=11.2,text="It eats just one berry a day. By enduring hunger, its spirit is tempered and made sharper."},
  [308]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=69.4,weightKg=31.5,text="Through yoga training, it has honed its sixth sense. Its movements are elegant."},
  [309]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=33.5,weightKg=15.2,text="Using electricity stored in its fur, it stimulates its muscles to heighten its reaction speed."},
  [310]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=88.6,weightKg=40.2,text="It discharges electricity from its mane. It creates a thundercloud overhead to drop lightning bolts."},
  [311]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=9.3,weightKg=4.2,text="It cheers on friends with pom-poms made of sparks. It drains power from telephone poles."},
  [312]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=9.3,weightKg=4.2,text="It cheers on friends. If its friends are losing, its body lets off more and more sparks."},
  [313]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=39.0,weightKg=17.7,text="It communicates with others by lighting up its rear at night. It loves ILLUMISE’s sweet aroma."},
  [314]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=39.0,weightKg=17.7,text="With its sweet aroma, it guides VOLBEAT to draw signs with light in the night sky."},
  [315]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=4.4,weightKg=2.0,text="ROSELIA raised on clean drinking water are known to grow vividly colored flowers."},
  [316]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=22.7,weightKg=10.3,text="Almost all its body is its stomach. Its harsh digestive juices quickly dissolve anything it swallows."},
  [317]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=176.4,weightKg=80.0,text="It swallows anything whole. It sweats toxic fluids from its follicles to douse foes."},
  [318]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=45.9,weightKg=20.8,text="They swarm any foe that invades their territory. Their sharp fangs can tear out boat hulls."},
  [319]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=195.8,weightKg=88.8,text="Its fangs rip through sheet iron. It swims at 75 mph and is known as “The Bully of the Sea.”"},
  [320]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=286.6,weightKg=130.0,text="On sunny days, it lands on beaches to bounce like a ball and play. It spouts water from its nose."},
  [321]={kind="POKEMON",heightFt=47,heightIn=7,heightM=14.5,weight=877.4,weightKg=398.0,text="The biggest of all Pokémon. It can dive to a depth of almost 10,000 feet on only one breath."},
  [322]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=52.9,weightKg=24.0,text="Its humped back stores intensely hot magma. In rain, the magma cools, slowing its movement."},
  [323]={kind="POKEMON",heightFt=6,heightIn=3,heightM=1.9,weight=485.0,weightKg=220.0,text="It has volcanoes on its back. If magma builds up in its body, it shudders, then erupts violently."},
  [324]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=177.3,weightKg=80.4,text="It burns coal inside its shell for energy. It blows out black soot if it is endangered."},
  [325]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=67.5,weightKg=30.6,text="It bounces constantly, using its tail like a spring. The shock of bouncing keeps its heart beating."},
  [326]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=157.6,weightKg=71.5,text="It uses black pearls to amplify its psycho-power. It does an odd dance to gain control over foes."},
  [327]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=11.0,weightKg=5.0,text="No two SPINDA have the same pattern of spots. Its tottering step fouls the aim of foes."},
  [328]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=33.1,weightKg=15.0,text="It makes a conical pit in desert sand and lies in wait at the bottom for prey to come tumbling down."},
  [329]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=33.7,weightKg=15.3,text="It violently shudders its wings, generating ultrasonic waves to induce headaches in people."},
  [330]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=180.8,weightKg=82.0,text="It whips up sandstorms with powerful flaps of its wings. It is known as “The Desert Spirit.”"},
  [331]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=113.1,weightKg=51.3,text="By storing water in its body, this desert dweller can survive for 30 days without water."},
  [332]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=170.6,weightKg=77.4,text="It becomes active at night, seeking prey that is exhausted from the day’s desert heat."},
  [333]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=2.6,weightKg=1.2,text="Its wings are like cotton tufts. If it perches on someone’s head, it looks like a cotton hat."},
  [334]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=45.4,weightKg=20.6,text="It looks like a fluffy cloud when it is in flight. It hums with its soprano voice."},
  [335]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=88.8,weightKg=40.3,text="It has feuded with SEVIPER for many generations. Its sharp claws are its biggest weapons."},
  [336]={kind="POKEMON",heightFt=8,heightIn=10,heightM=2.7,weight=115.7,weightKg=52.5,text="For many generations, it has feuded with ZANGOOSE. It whets its bladed tail on rocks for battle."},
  [337]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=370.4,weightKg=168.0,text="Because it turns active on nights of the full moon, it is said to have some link to the lunar phases."},
  [338]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=339.5,weightKg=154.0,text="A new Pokémon species, rumored to be from the sun. It gives off light while spinning."},
  [339]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=4.2,weightKg=1.9,text="It coats its entire body with a slimy fluid so it can squirm and slip away if grabbed."},
  [340]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=52.0,weightKg=23.6,text="It is very territorial. It repels foes by setting off tremors that extend over a three-mile radius."},
  [341]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=25.4,weightKg=11.5,text="Its hardy vitality enables it to adapt to any environment. Its pincers will never release prey."},
  [342]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=72.3,weightKg=32.8,text="It is a ruffian that uses its pincers to pick up and toss out other Pokémon from its pond."},
  [343]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=47.4,weightKg=21.5,text="It moves by spinning on its foot. It is a rare Pokémon that was discovered in ancient ruins."},
  [344]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=238.1,weightKg=108.0,text="An ancient clay figurine that came to life as a Pokémon from exposure to a mysterious ray of light."},
  [345]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=52.5,weightKg=23.8,text="It lived on the seafloor 100 million years ago and was reanimated scientifically."},
  [346]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=133.2,weightKg=60.4,text="It lives in the shallows of warm seas. When the tide goes out, it digs up prey from beaches."},
  [347]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=27.6,weightKg=12.5,text="A Pokémon ancestor that was reanimated from a fossil. It lived in the sea and hunted with claws."},
  [348]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=150.4,weightKg=68.2,text="It went ashore after evolving. Its entire body is clad in a sturdy armor."},
  [349]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=16.3,weightKg=7.4,text="It is famous for its shabby appearance. While populous, they tend to cluster in set locations."},
  [350]={kind="POKEMON",heightFt=20,heightIn=4,heightM=6.2,weight=357.1,weightKg=162.0,text="When people bicker, it is said to arise from the depths of lakes to becalm violent hearts."},
  [351]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=1.8,weightKg=0.8,text="Its appearance changes with the weather. Recently, its molecules were found to be just like water."},
  [352]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=48.5,weightKg=22.0,text="It can freely change its body’s color. The zigzag pattern on its belly doesn’t change, however."},
  [353]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=5.1,weightKg=2.3,text="It loves vengeful emotions and hangs in rows under the eaves of houses where vengeful people live."},
  [354]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=27.6,weightKg=12.5,text="A doll that became a Pokémon over its grudge from being junked. It seeks the child that disowned it."},
  [355]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=33.1,weightKg=15.0,text="It doggedly pursues its prey wherever it goes. However, the chase is abandoned at sunrise."},
  [356]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=67.5,weightKg=30.6,text="Its body is hollow. It is said that those who look into its body are sucked into the void."},
  [357]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=220.5,weightKg=100.0,text="Because it continually ate only its favorite fruit, the fruit started growing around its neck."},
  [358]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=2.2,weightKg=1.0,text="To knock foes flying, it makes the air shudder with its cries. It converses using seven cries."},
  [359]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=103.6,weightKg=47.0,text="It senses coming disasters and appears before people only to warn them of impending danger."},
  [360]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=30.9,weightKg=14.0,text="It grows strong by pushing up against others en masse. It loves eating sweet fruit."},
  [361]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=37.0,weightKg=16.8,text="In the snow country, certain folklore says a house will prosper if a SNORUNT lives there."},
  [362]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=565.5,weightKg=256.5,text="To protect itself, it clads its body in an armor of ice, made by freezing moisture in the air."},
  [363]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=87.1,weightKg=39.5,text="It rolls across ice floes to reach shore because its body is poorly shaped for swimming."},
  [364]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=193.1,weightKg=87.6,text="It habitually spins things on its nose. By doing so, it learns textures and odors."},
  [365]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=332.0,weightKg=150.6,text="It shatters ice with its big tusks. Its thick blubber repels not only the cold, but also enemy attacks."},
  [366]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=115.7,weightKg=52.5,text="It makes a single pearl during its lifetime. The pearl is said to amplify psychic power."},
  [367]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=59.5,weightKg=27.0,text="It lives deep in the sea. With a tail shaped like a small fish, it attracts unsuspecting prey."},
  [368]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=49.8,weightKg=22.6,text="It lives at the bottom of the sea. In the springtime, its pink body turns more vivid for some reason."},
  [369]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=51.6,weightKg=23.4,text="A rare Pokémon discovered during a deep-sea exploration. It has not changed in over 100 million years."},
  [370]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=19.2,weightKg=8.7,text="It lives in warm seas. It is said that a couple finding this Pokémon will be blessed with eternal love."},
  [371]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=92.8,weightKg=42.1,text="Dreaming of one day flying, it practices by leaping off cliffs every day."},
  [372]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=243.6,weightKg=110.5,text="Within its rugged shell, its cells have begun changing. The shell peels off the instant it evolves."},
  [373]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=226.2,weightKg=102.6,text="As a result of its long-held dream of flying, its cellular structure changed, and wings grew out."},
  [374]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=209.9,weightKg=95.2,text="It converses with others by using magnetic pulses. In a swarm, they move in perfect unison."},
  [375]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=446.4,weightKg=202.5,text="It is formed by two BELDUM joining together. Its steel body won’t be scratched if it collides with a jet."},
  [376]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=1212.5,weightKg=550.0,text="METANG combined to form it. With four brains, it has the intelligence of a supercomputer."},
  [377]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=507.1,weightKg=230.0,text="Its entire body is made of rock. If any part chips off in battle, it attaches rocks to repair itself."},
  [378]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=385.8,weightKg=175.0,text="Its body is made of ice from the ice age. It controls frigid air of -328 degrees Fahrenheit."},
  [379]={kind="POKEMON",heightFt=6,heightIn=3,heightM=1.9,weight=451.9,weightKg=205.0,text="Tempered by pressure underground over tens of thousands of years, its body cannot be scratched."},
  [380]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=88.2,weightKg=40.0,text="Its body is covered with a down that can refract light in such a way that it becomes invisible."},
  [381]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=132.3,weightKg=60.0,text="A highly intelligent Pokémon. By folding back its wings in flight, it can overtake jet planes."},
  [382]={kind="POKEMON",heightFt=14,heightIn=9,heightM=4.5,weight=776.0,weightKg=352.0,text="It is said to have widened the seas by causing downpours. It had been asleep in a marine trench."},
  [383]={kind="POKEMON",heightFt=11,heightIn=6,heightM=3.5,weight=2094.4,weightKg=950.0,text="It had been asleep in underground magma ever since it fiercely fought KYOGRE long ago."},
  [384]={kind="POKEMON",heightFt=23,heightIn=0,heightM=7.0,weight=455.3,weightKg=206.5,text="It lives in the ozone layer far above the clouds and cannot be seen from the ground."},
  [385]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=2.4,weightKg=1.1,text="It is said to have the ability to grant any wish for just one week every thousand years."},
  [386]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=134.0,weightKg=60.8,text="An alien virus that fell to earth on a meteor underwent a DNA mutation to become this Pokémon."},
  [387]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=22.5,weightKg=10.2,text="Made from soil, the shell on its back hardens when it drinks water. It lives along lakes."},
  [388]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=213.8,weightKg=97.0,text="It lives along water in forests. In the daytime, it leaves the forest to sunbathe its treed shell."},
  [389]={kind="POKEMON",heightFt=7,heightIn=3,heightM=2.2,weight=683.4,weightKg=310.0,text="Small Pokémon occasionally gather on its unmoving back to begin building their nests."},
  [390]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=13.7,weightKg=6.2,text="It agilely scales sheer cliffs to live atop craggy mountains. Its fire is put out when it sleeps."},
  [391]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=48.5,weightKg=22.0,text="To intimidate attackers, it stretches the fire on its tail to make itself appear bigger."},
  [392]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=121.3,weightKg=55.0,text="It uses a special kind of martial arts involving all its limbs. Its fire never goes out."},
  [393]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=11.5,weightKg=5.2,text="Because it is very proud, it hates accepting food from people. Its thick down guards it from cold."},
  [394]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=50.7,weightKg=23.0,text="It lives alone, away from others. Apparently, every one of them believes it is the most important."},
  [395]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=186.3,weightKg=84.5,text="The three horns that extend from its beak attest to its power. The leader has the biggest horns."},
  [396]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=4.4,weightKg=2.0,text="They flock in great numbers. Though small, they flap their wings with great power."},
  [397]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=34.2,weightKg=15.5,text="It flies around forests and fields in search of bug Pokémon. It stays within a huge flock."},
  [398]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=54.9,weightKg=24.9,text="It has a savage nature. It will courageously challenge foes that are much larger."},
  [399]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=44.1,weightKg=20.0,text="With nerves of steel, nothing can perturb it. It is more agile and active than it appears."},
  [400]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=69.4,weightKg=31.5,text="It makes its nest by damming streams with bark and mud. It is known as an industrious worker."},
  [401]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=4.9,weightKg=2.2,text="It shakes its head back to front, causing its antennae to hit each other and sound like a xylophone."},
  [402]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=56.2,weightKg=25.5,text="It crosses its knifelike arms in front of its chest when it cries. It can compose melodies ad lib."},
  [403]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=20.9,weightKg=9.5,text="All of its fur dazzles if danger is sensed. It flees while the foe is momentarily blinded."},
  [404]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=67.2,weightKg=30.5,text="Its claws loose electricity with enough amperage to cause fainting. They live in small groups."},
  [405]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=92.6,weightKg=42.0,text="It has eyes that can see through anything. It spots and captures prey hiding behind objects."},
  [406]={kind="POKEMON",heightFt=0,heightIn=8,heightM=0.2,weight=2.6,weightKg=1.2,text="Over the winter, it closes its bud and endures the cold. In spring, the bud opens and releases pollen."},
  [407]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=32.0,weightKg=14.5,text="It attracts prey with a sweet aroma, then downs it with thorny whips hidden in its arms."},
  [408]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=69.4,weightKg=31.5,text="It lived in jungles around 100 million years ago. Its skull is as hard as iron."},
  [409]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=226.0,weightKg=102.5,text="Its powerful head butt has enough power to shatter even the most durable things upon impact."},
  [410]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=125.7,weightKg=57.0,text="A Pokémon that lived in jungles around 100 million years ago. Its facial hide is extremely hard."},
  [411]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=329.6,weightKg=149.5,text="Any frontal attack is repulsed. It is a docile Pokémon that feeds on grass and berries."},
  [412]={kind="POKEMON",heightFt=0,heightIn=8,heightM=0.2,weight=7.5,weightKg=3.4,text="To shelter itself from cold, wintry winds, it covers itself with a cloak made of twigs and leaves."},
  [413]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=14.3,weightKg=6.5,text="When BURMY evolved, its cloak became a part of this Pokémon’s body. The cloak is never shed."},
  [414]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=51.4,weightKg=23.3,text="It loves the honey of flowers and steals honey collected by COMBEE."},
  [415]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=12.1,weightKg=5.5,text="A Pokémon formed by three others. It busily carries sweet floral honey to VESPIQUEN."},
  [416]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=84.9,weightKg=38.5,text="Its abdomen is a honeycomb for grubs. It raises its grubs on honey collected by COMBEE."},
  [417]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=8.6,weightKg=3.9,text="It makes fur balls that crackle with static electricity. It stores them with berries in tree holes."},
  [418]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=65.0,weightKg=29.5,text="It has a flotation sac that is like an inflatable collar. It floats on water with its head out."},
  [419]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=73.9,weightKg=33.5,text="It floats using its well-developed flotation sac. It assists in the rescues of drowning people."},
  [420]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=7.3,weightKg=3.3,text="The small ball holds the nutrients needed for evolution. Apparently, it is very sweet and tasty."},
  [421]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=20.5,weightKg=9.3,text="It blooms during times of strong sunlight. It tries to make up for everything it endured as a bud."},
  [422]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=13.9,weightKg=6.3,text="Its colors and shapes differ from region to region. In the Sinnoh region, two types are confirmed."},
  [423]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=65.9,weightKg=29.9,text="It has a pliable body without any bones. If any part of its body is torn off, it grows right back."},
  [424]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=44.8,weightKg=20.3,text="To eat, it deftly shucks nuts with its two tails. It rarely uses its arms now."},
  [425]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=2.6,weightKg=1.2,text="A Pokémon formed by the spirits of people and Pokémon. It loves damp, humid seasons."},
  [426]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=33.1,weightKg=15.0,text="It’s drowzy in daytime, but flies off in the evening in big groups. No one knows where they go."},
  [427]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=12.1,weightKg=5.5,text="It slams foes by sharply uncoiling its rolled ears. It stings enough to make a grown-up cry in pain."},
  [428]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=73.4,weightKg=33.3,text="An extremely cautious Pokémon. It cloaks its body with its fluffy ear fur when it senses danger."},
  [429]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=9.7,weightKg=4.4,text="Its cries sound like incantations. Those hearing it are tormented by headaches and hallucinations."},
  [430]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=60.2,weightKg=27.3,text="Becoming active at night, it is known to swarm with numerous MURKROW in tow."},
  [431]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=8.6,weightKg=3.9,text="It claws if displeased and purrs when affectionate. Its fickleness is very popular among some."},
  [432]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=96.6,weightKg=43.8,text="It is a brazen brute that barges its way into another Pokémon’s nest and claims it as its own."},
  [433]={kind="POKEMON",heightFt=0,heightIn=8,heightM=0.2,weight=1.3,weightKg=0.6,text="It emits cries by agitating an orb at the back of its throat. It moves with flouncing hops."},
  [434]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=42.3,weightKg=19.2,text="It protects itself by spraying a noxious fluid from its rear. The stench lingers for 24 hours."},
  [435]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=83.8,weightKg=38.0,text="It sprays a vile-smelling fluid from the tip of its tail to attack. Its range is over 160 feet."},
  [436]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=133.4,weightKg=60.5,text="Implements shaped like it were discovered in ancient tombs. It is unknown if they are related."},
  [437]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=412.3,weightKg=187.0,text="One caused a news sensation when it was dug up at a construction site after a 2,000-year sleep."},
  [438]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=33.1,weightKg=15.0,text="It looks as if it is always crying. It is actually adjusting its body’s fluid levels by eliminating excess."},
  [439]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=28.7,weightKg=13.0,text="It habitually mimics foes. Once mimicked, the foe cannot take its eyes off this Pokémon."},
  [440]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=53.8,weightKg=24.4,text="It loves round white things. It carries an egg-shaped rock in imitation of CHANSEY."},
  [441]={kind="POKEMON",heightFt=1,heightIn=8,heightM=0.5,weight=4.2,weightKg=1.9,text="It can learn and speak human words. If they gather, they all learn the same saying."},
  [442]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=238.1,weightKg=108.0,text="A Pokémon that was formed by 108 spirits. It is bound to a fissure in an odd keystone."},
  [443]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=45.2,weightKg=20.5,text="It nests in small, horizontal holes in cave walls. It pounces to catch prey that stray too close."},
  [444]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=123.5,weightKg=56.0,text="There is a long-held belief that medicine made from its scales will heal even incurable illnesses."},
  [445]={kind="POKEMON",heightFt=6,heightIn=3,heightM=1.9,weight=209.4,weightKg=95.0,text="When it folds up its body and extends its wings, it looks like a jet plane. It flies at sonic speed."},
  [446]={kind="POKEMON",heightFt=2,heightIn=0,heightM=0.6,weight=231.5,weightKg=105.0,text="It wolfs down its weight in food once a day, swallowing food whole with almost no chewing."},
  [447]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=44.5,weightKg=20.2,text="The aura that emanates from its body intensifies to alert others if it is afraid or sad."},
  [448]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=119.0,weightKg=54.0,text="It has the ability to sense the auras of all things. It understands human speech."},
  [449]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=109.1,weightKg=49.5,text="It lives in arid places. Instead of perspiration, it expels grainy sand from its body."},
  [450]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=661.4,weightKg=300.0,text="It blasts internally stored sand from ports on its body to create a towering twister for attack."},
  [451]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=26.5,weightKg=12.0,text="It grips prey with its tail claws and injects poison. It tenaciously hangs on until the poison takes."},
  [452]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=135.6,weightKg=61.5,text="It has the power in its clawed arms to make scrap of a car. The tips of its claws release poison."},
  [453]={kind="POKEMON",heightFt=2,heightIn=4,heightM=0.7,weight=50.7,weightKg=23.0,text="Its cheeks hold poison sacs. It tries to catch foes off guard to jab them with toxic fingers."},
  [454]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=97.9,weightKg=44.4,text="Its knuckle claws secrete a toxin so vile that even a scratch could prove fatal."},
  [455]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=59.5,weightKg=27.0,text="It attracts prey with its sweet- smelling saliva, then chomps down. It takes a whole day to eat prey."},
  [456]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=15.4,weightKg=7.0,text="After long exposure to sunlight, the patterns on its tail fins shine vividly when darkness arrives."},
  [457]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=52.9,weightKg=24.0,text="It lives on the deep-sea floor. It attracts prey by flashing the patterns on its four tail fins."},
  [458]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=143.3,weightKg=65.0,text="A friendly Pokémon that captures the subtle flows of seawater using its two antennae."},
  [459]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=111.3,weightKg=50.5,text="It lives on snowy mountains. Having had little contact with humans, it is boldly inquisitive."},
  [460]={kind="POKEMON",heightFt=7,heightIn=3,heightM=2.2,weight=298.7,weightKg=135.5,text="It whips up blizzards in mountains that are always buried in snow. It is the abominable snowman."},
  [461]={kind="POKEMON",heightFt=3,heightIn=7,heightM=1.1,weight=75.0,weightKg=34.0,text="They live in cold regions, forming groups of four or five that hunt prey with impressive coordination."},
  [462]={kind="POKEMON",heightFt=3,heightIn=11,heightM=1.2,weight=396.8,weightKg=180.0,text="It evolved from exposure to a special magnetic field. Three units generate magnetism."},
  [463]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=308.6,weightKg=140.0,text="It wraps things with its extensible tongue. Getting too close to it will leave you soaked with drool."},
  [464]={kind="POKEMON",heightFt=7,heightIn=10,heightM=2.4,weight=623.5,weightKg=282.8,text="It puts rocks in holes in its palms and uses its muscles to shoot them. GEODUDE are shot at rare times."},
  [465]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=283.5,weightKg=128.6,text="It ensnares prey by extending arms made of vines. Losing arms to predators does not trouble it."},
  [466]={kind="POKEMON",heightFt=5,heightIn=11,heightM=1.8,weight=305.6,weightKg=138.6,text="It pushes the tips of its two tails against the foe, then lets loose with over 20,000 volts of power."},
  [467]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=149.9,weightKg=68.0,text="It blasts fireballs of over 3,600 degrees F from the ends of its arms. It lives in volcanic craters."},
  [468]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=83.8,weightKg=38.0,text="It will never appear where there is strife. Its sightings have become rare recently."},
  [469]={kind="POKEMON",heightFt=6,heightIn=3,heightM=1.9,weight=113.5,weightKg=51.5,text="By churning its wings, it creates shock waves that inflict critical internal injuries to foes."},
  [470]={kind="POKEMON",heightFt=3,heightIn=3,heightM=1.0,weight=56.2,weightKg=25.5,text="Just like a plant, it uses photosynthesis. As a result, it is always enveloped in clear air."},
  [471]={kind="POKEMON",heightFt=2,heightIn=7,heightM=0.8,weight=57.1,weightKg=25.9,text="As a protective technique, it can completely freeze its fur to make its hairs stand like needles."},
  [472]={kind="POKEMON",heightFt=6,heightIn=7,heightM=2.0,weight=93.7,weightKg=42.5,text="It observes prey while hanging inverted from branches. When the chance presents itself, it swoops!"},
  [473]={kind="POKEMON",heightFt=8,heightIn=2,heightM=2.5,weight=641.5,weightKg=291.0,text="Its impressive tusks are made of ice. The population thinned when it turned warm after the ice age."},
  [474]={kind="POKEMON",heightFt=2,heightIn=11,heightM=0.9,weight=75.0,weightKg=34.0,text="Additional software was installed to make it a better Pokémon. It began acting oddly, however."},
  [475]={kind="POKEMON",heightFt=5,heightIn=3,heightM=1.6,weight=114.6,weightKg=52.0,text="A master of courtesy and swordsmanship, it fights using extending swords on its elbows."},
  [476]={kind="POKEMON",heightFt=4,heightIn=7,heightM=1.4,weight=749.6,weightKg=340.0,text="It exudes strong magnetism from all over. It controls three small units called Mini-Noses."},
  [477]={kind="POKEMON",heightFt=7,heightIn=3,heightM=2.2,weight=235.0,weightKg=106.6,text="The antenna on its head captures radio waves from the world of spirits that command it to take people there."},
  [478]={kind="POKEMON",heightFt=4,heightIn=3,heightM=1.3,weight=58.6,weightKg=26.6,text="It freezes foes with an icy breath nearly -60 degrees F. What seems to be its body is actually hollow."},
  [479]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=0.7,weightKg=0.3,text="Its body is composed of plasma. It is known to infiltrate electronic devices and wreak havoc."},
  [480]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=0.7,weightKg=0.3,text="Known as “The Being of Knowledge.” It is said that it can wipe out the memory of those who see its eyes."},
  [481]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=0.7,weightKg=0.3,text="Known as “The Being of Emotion.” It taught humans the nobility of sorrow, pain, and joy."},
  [482]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=0.7,weightKg=0.3,text="Known as “The Being of Willpower.” It sleeps at the bottom of a lake to keep the world in balance."},
  [483]={kind="POKEMON",heightFt=17,heightIn=9,heightM=5.4,weight=1505.8,weightKg=683.0,text="It has the power to control time. It appears in Sinnoh-region myths as an ancient deity."},
  [484]={kind="POKEMON",heightFt=13,heightIn=9,heightM=4.2,weight=740.8,weightKg=336.0,text="It has the ability to distort space. It is described as a deity in Sinnoh-region mythology."},
  [485]={kind="POKEMON",heightFt=5,heightIn=7,heightM=1.7,weight=948.0,weightKg=430.0,text="It dwells in volcanic caves. It digs in with its cross-shaped feet to crawl on ceilings and walls."},
  [486]={kind="POKEMON",heightFt=12,heightIn=2,heightM=3.7,weight=925.9,weightKg=420.0,text="There is an enduring legend that states this Pokémon towed continents with ropes."},
  [487]={kind="POKEMON",heightFt=14,heightIn=9,heightM=4.5,weight=1653.5,weightKg=750.0,text="A Pokémon that is said to live in a world on the reverse side of ours. It appears in an ancient cemetery."},
  [488]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=188.7,weightKg=85.6,text="Shiny particles are released from its wings like a veil. It is said to represent the crescent moon."},
  [489]={kind="POKEMON",heightFt=1,heightIn=4,heightM=0.4,weight=6.8,weightKg=3.1,text="A Pokémon that lives in warm seas. It inflates the flotation sac on its head to drift and search for food."},
  [490]={kind="POKEMON",heightFt=1,heightIn=0,heightM=0.3,weight=3.1,weightKg=1.4,text="Born on a cold seafloor, it will swim great distances to return to its birthplace."},
  [491]={kind="POKEMON",heightFt=4,heightIn=11,heightM=1.5,weight=111.3,weightKg=50.5,text="It can lull people to sleep and make them dream. It is active during nights of the new moon."},
  [492]={kind="POKEMON",heightFt=0,heightIn=8,heightM=0.2,weight=4.6,weightKg=2.1,text="It lives in flower patches and avoids detection by curling up to look like a flowering plant."},
  [493]={kind="POKEMON",heightFt=10,heightIn=6,heightM=3.2,weight=705.5,weightKg=320.0,text="It is described in mythology as the Pokémon that shaped the universe with its 1,000 arms."},
}
